import java.util.*;
import java.io.*;

public class Main {
    static int n, totalCount, answer;
    static long[] sumArr = new long[15];
    static List<Integer>[] vecs = new ArrayList[15];

    static {
        for (int i = 0; i < 15; i++) {
            vecs[i] = new ArrayList<>();
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        buildSequences(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(vecs[i]);
        }
        totalCount = 0;
        answer = 0;
        for (int i = 1; i <= 9; i++) {
            explore(i);
        }
        System.out.println(answer);
    }

    static void buildSequences(int level, int num) {
        if (level == 7) return;
        totalCount++;
        long val = ((long)(totalCount - num) % 998244353 + 998244353) % 998244353;
        vecs[level].add((int) val);
        sumArr[level] = (sumArr[level] + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            buildSequences(level + 1, num * 10 + digit);
        }
    }

    static void explore(int x) {
        if (x > n) return;
        if (x * 1000000 + 999999 <= n && x * 10 * 1000000 > n) {
            int current = totalCount;
            for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
                List<Integer> vec = vecs[i];
                int sizeVec = vec.size();
                long diffVal = ((long)(current - x * mul) % 998244353 + 998244353) % 998244353;
                int target = (int) (lowerBound(vec, (int)(1000000000 - diffVal)));
                answer = (int) ((answer + diffVal * sizeVec + sumArr[i]) % 1000000007);
                long subtractVal = (998244353L * (sizeVec - target)) % 1000000007;
                answer = (int) ((answer - subtractVal + 1000000007) % 1000000007);
                totalCount += sizeVec;
            }
            return;
        }
        totalCount++;
        long addVal = ((long)(totalCount - x) % 998244353 + 998244353) % 998244353;
        answer = (int) ((answer + addVal) % 1000000007);
        for (int i = 0; i <= 9; i++) {
            explore(x * 10 + i);
        }
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
